import{_ as l,C as r,o as t,c as i,a4 as o,E as d,j as e,a as s}from"./chunks/framework.BAT2SzCK.js";const f=JSON.parse('{"title":"📐 统一物模型 (TSL) 规范","description":"","frontmatter":{},"headers":[],"relativePath":"iot/tsl.md","filePath":"iot/tsl.md","lastUpdated":1794302070000}'),p={name:"iot/tsl.md"};function c(u,a,h,b,m,v){const n=r("TslModelValidator");return t(),i("div",null,[a[0]||(a[0]=o(`<h1 id="📐-统一物模型-tsl-规范" tabindex="-1">📐 统一物模型 (TSL) 规范 <a class="header-anchor" href="#📐-统一物模型-tsl-规范" aria-label="Permalink to &quot;📐 统一物模型 (TSL) 规范&quot;">​</a></h1><p>物模型（Thing Specification Language, TSL）是对物理世界设备数字化表述的标准语言。无论底层采用哪种传输协议，MzMedia 均将设备抽象为标准的三大维度要素：</p><hr><h2 id="_1-物模型三大核心要素" tabindex="-1">1. 物模型三大核心要素 <a class="header-anchor" href="#_1-物模型三大核心要素" aria-label="Permalink to &quot;1. 物模型三大核心要素&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span> ┌────────────────────────────────────────────────────────┐</span></span>
<span class="line"><span> │                   统一物模型 (TSL)                     │</span></span>
<span class="line"><span> ├────────────────────────┬───────────────────────────────┤</span></span>
<span class="line"><span> │ 1. 属性 (Property)     │ 设备运行状态 (如温度、压力、电量)│</span></span>
<span class="line"><span> ├────────────────────────┼───────────────────────────────┤</span></span>
<span class="line"><span> │ 2. 服务 (Service)      │ 平台对设备下发的指令 (重启、开阀)│</span></span>
<span class="line"><span> ├────────────────────────┼───────────────────────────────┤</span></span>
<span class="line"><span> │ 3. 事件 (Event)        │ 设备突发主动上报 (故障、低电告警)│</span></span>
<span class="line"><span> └────────────────────────┴───────────────────────────────┘</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><h3 id="要素一-属性-property" tabindex="-1">要素一：属性 (Property) <a class="header-anchor" href="#要素一-属性-property" aria-label="Permalink to &quot;要素一：属性 (Property)&quot;">​</a></h3><ul><li>表示设备当前的测量值或静态参数；</li><li>包含只读（<code>r</code>）与读写（<code>rw</code>）权限；</li><li>支持丰富的数据类型：<code>int</code>, <code>float</code>, <code>double</code>, <code>string</code>, <code>bool</code>, <code>enum</code>, <code>array</code>, <code>struct</code>；</li><li>支持定义数值上下限、单位（如 <code>℃</code>, <code>MPa</code>, <code>V</code>, <code>A</code>）以及步长。</li></ul><h3 id="要素二-服务-service" tabindex="-1">要素二：服务 (Service) <a class="header-anchor" href="#要素二-服务-service" aria-label="Permalink to &quot;要素二：服务 (Service)&quot;">​</a></h3><ul><li>平台向设备下发的控制指令，包含入参（Input Parameters）与出参（Output Parameters）；</li><li>支持同步执行模式（等待设备返回结果）与异步执行模式（下发后通过设备事件异步回调确认）。</li></ul><h3 id="要素三-事件-event" tabindex="-1">要素三：事件 (Event) <a class="header-anchor" href="#要素三-事件-event" aria-label="Permalink to &quot;要素三：事件 (Event)&quot;">​</a></h3><ul><li>设备运行过程中主动向平台上报的特定事件；</li><li>分为三个事件等级： <ul><li><strong>信息 (Info)</strong>：常规事件（如“定时自检正常”、“固件升级开始”）；</li><li><strong>告警 (Warn)</strong>：阈值告警（如“液位偏高”、“滤波网即将到期”）；</li><li><strong>故障 (Error)</strong>：严重事件（如“电机堵转”、“主板过温停机”）。</li></ul></li></ul><hr><h2 id="tsl-validator" tabindex="-1">2. 在线物模型解析与语法校验器 <a class="header-anchor" href="#tsl-validator" aria-label="Permalink to &quot;2. 在线物模型解析与语法校验器 {#tsl-validator}&quot;">​</a></h2><p>您可以通过下方交互器切换预置工业设备模板，或直接粘贴业务 JSON 进行实时规范性验证：</p>`,14)),d(n),a[1]||(a[1]=e("hr",null,null,-1)),a[2]||(a[2]=e("h2",{id:"_3-设备影子-device-shadow",tabindex:"-1"},[s("3. 设备影子 (Device Shadow) "),e("a",{class:"header-anchor",href:"#_3-设备影子-device-shadow","aria-label":'Permalink to "3. 设备影子 (Device Shadow)"'},"​")],-1)),a[3]||(a[3]=e("p",null,[s("在弱网或移动应用场景中，设备并不总是在线。MzMedia 提供了"),e("strong",null,"设备影子"),s("机制：")],-1)),a[4]||(a[4]=e("ul",null,[e("li",null,"缓存设备最新的物理属性值（Reported 状态）；"),e("li",null,"缓存平台期望下发但设备尚未联机确认的控制值（Desired 状态）；"),e("li",null,"设备重新上线时，网关自动将差量变更推送到设备端并清空影子指令。")],-1))])}const g=l(p,[["render",c]]);export{f as __pageData,g as default};
